const G = 24;
const byCode = Object.fromEntries(countries.map(c => [c.code, c]));
export const stampFor = code => byCode[String(code || '').toUpperCase()] || null;

// best guess from the browser's language settings (e.g. "da-DK" -> "DK"); null if no language names a region
export function detectCountry() {
  const langs = typeof navigator === 'undefined' ? [] : navigator.languages || [navigator.language];
  for (const l of langs) {
    try { const r = new Intl.Locale(l).region; if (r && byCode[r]) return r; } catch { /* skip bad tags */ }
  }
  return null;
}

// temperate southern-hemisphere countries get their seasons flipped
const SOUTH = new Set(['AR', 'AU', 'BW', 'CL', 'LS', 'NA', 'NZ', 'PY', 'SZ', 'UY', 'ZA']);
export function seasonFor(code, date = new Date()) {
  const m = date.getMonth(), q = Math.floor(((m + 1) % 12) / 3);      // 0 Dec–Feb, 1 Mar–May, 2 Jun–Aug, 3 Sep–Nov
  const north = ['winter', 'spring', 'summer', 'fall'];
  return SOUTH.has(String(code || '').toUpperCase()) ? north[(q + 2) % 4] : north[q];
}

// 5-row pixel font: 3 dots wide, with wider K, M, N, W (rows separated by '/')
const FONT = {
  A: '010101111101101', B: '110101110101110', C: '011100100100011', D: '110101101101110', E: '111100110100111',
  F: '111100110100100', G: '011100101101011', H: '101101111101101', I: '111010010010111', J: '001001001101010',
  K: '1001/1010/1100/1010/1001', L: '100100100100111', M: '10001/11011/10101/10001/10001', N: '1001/1101/1011/1001/1001', O: '010101101101010',
  P: '110101110100100', Q: '010101101110011', R: '110101110101101', S: '011100010001110', T: '111010010010010',
  U: '101101101101111', V: '101101101101010', W: '10001/10001/10101/11011/10001', X: '101101010101101', Y: '101101010010010',
  Z: '111001010100111', 0: '111101101101111', 1: '010110010010111', 2: '110001010100111', 3: '110001010001110',
  4: '101101111001001', 5: '111100110001110', 6: '011100111101111', 7: '111001010010010', 8: '111101111101111',
  9: '111101111001110', '-': '000000111000000', ' ': '000000000000000',
};
const glyph = ch => { const g = FONT[ch] || FONT[' ']; const rows = g.includes('/') ? g.split('/') : g.match(/.{3}/g); return { rows, w: rows[0].length }; };
const textWidth = s => [...s].reduce((t, ch) => t + glyph(ch).w + 1, 0) - 1;

function bitmap(w, h) {
  const b = new Uint8Array(w * h);
  const set = (x, y, v = 1) => { if (x >= 0 && y >= 0 && x < w && y < h) b[y * w + x] = v; };
  return {
    w, h, b, set,
    rect: (x0, y0, x1, y1, v = 1) => { for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) set(x, y, v); },
    ring: (k, every = 1) => {
      for (let x = k; x < w - k; x++) if ((x - k) % every === 0 || x === w - 1 - k) { set(x, k); set(x, h - 1 - k); }
      for (let y = k; y < h - k; y++) if ((y - k) % every === 0 || y === h - 1 - k) { set(k, y); set(w - 1 - k, y); }
    },
    text: (s, x, y, v = 1) => {
      for (const ch of s) { const { rows, w } = glyph(ch); rows.forEach((r, dy) => [...r].forEach((c, dx) => c === '1' && set(x + dx, y + dy, v))); x += w + 1; }
    },
    path: () => {
      let d = '';
      for (let y = 0; y < h; y++) for (let x = 0; x < w;) {
        if (!b[y * w + x]) { x++; continue; }
        let e = x; while (e < w && b[y * w + e]) e++;
        d += `M${x} ${y}h${e - x}v1h${x - e}z`; x = e;
      }
      return d;
    },
  };
}

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const SEASONS = { spring: 'SPRING', summer: 'SUMMER', fall: 'FALL', autumn: 'AUTUMN', winter: 'WINTER' };

// symbol path data ("M x y h n v1 h-n z" runs) back to dots
function runsToBits(d, w, x0, y0, bm) {
  for (const m of d.matchAll(/M(\d+) (\d+)h(\d+)/g)) for (let i = 0; i < +m[3]; i++) bm.set(+m[1] + i + x0, +m[2] + y0);
}

// season: spring | summer | fall | autumn | winter | auto | none;  year: number | 'auto' | 'none'
function layout(code, { frame = 'perforated', season = 'auto', year = 'auto', tag = true, date = new Date() } = {}) {
  const c = stampFor(code);
  if (!c) throw new Error('Unknown country ' + code);
  const s = season === 'auto' ? seasonFor(c.code, date) : String(season || 'none').toLowerCase();
  const seasonText = SEASONS[s] || '';
  const yearText = year === 'auto' ? String(date.getFullYear()) : year === 'none' || year === '' || year == null ? '' : String(year).slice(0, 4);
  const tagText = tag ? c.code : '';
  const dated = seasonText || yearText || tagText;
  const framed = frame === 'perforated' || frame === 'line';

  // dot-grid layout: perforations on ring 0, frame line on ring 2, symbol, season, then a solid bar with code + year knocked out
  let W, H, sx, sy, bm;
  if (framed) {
    const barY = seasonText ? 39 : 32;                                  // no season line: the bar moves up
    W = dated ? 36 : 32; sx = (W - G) / 2; sy = dated ? 6 : 4;
    H = !dated ? 32 : (tagText || yearText) ? barY + 11 : 42;
    bm = bitmap(W, H);
    if (frame === 'perforated') bm.ring(0, 2);
    bm.ring(2);
    if (dated) {
      if (seasonText) bm.text(seasonText, Math.floor((W - textWidth(seasonText)) / 2), 32);
      if (tagText || yearText) {
        bm.rect(2, barY, W - 3, H - 3);
        if (tagText && yearText) { bm.text(tagText, 4, barY + 2, 0); bm.text(yearText, W - 4 - textWidth(yearText), barY + 2, 0); }
        else { const t = tagText || yearText; bm.text(t, Math.floor((W - textWidth(t)) / 2), barY + 2, 0); }
      }
    }
  } else {
    W = dated ? G + 4 : G; sx = (W - G) / 2; sy = 0; H = dated ? G + 3 + (seasonText ? 8 : 0) + ((tagText || yearText) ? 5 : -3) : G;
    bm = bitmap(W, H);
    let y = G + 3;
    if (seasonText) { bm.text(seasonText, Math.floor((W - textWidth(seasonText)) / 2), y); y += 8; }
    if (tagText) bm.text(tagText, 0, y);
    if (yearText) bm.text(yearText, W - textWidth(yearText), y);
  }
  const label = [c.name, seasonText && seasonText[0] + seasonText.slice(1).toLowerCase(), yearText].filter(Boolean).join(', ');
  return { c, W, H, sx, sy, bm, label };
}

export function stampSVG(code, opts = {}) {
  const { c, W, H, sx, sy, bm, label: auto } = layout(code, opts);
  const label = opts.title === undefined ? auto : opts.title;
  const size = opts.size ?? 96, px = typeof size === 'number' ? size : parseFloat(size) || 96;
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + px + '" height="' + +(px * H / W).toFixed(2) +
    '" fill="currentColor" shape-rendering="crispEdges"' + (label ? ' role="img" aria-label="' + esc(label) + '"' : ' aria-hidden="true"') + '>' +
    '<path d="' + bm.path() + '"/><path transform="translate(' + sx + ' ' + sy + ')" d="' + paths[c.symbol] + '"/></svg>';
}

// the whole stamp as dots: { w, h, bits: Uint8Array } (for canvas drawing, motion, etc.)
export function stampBits(code, opts = {}) {
  const { c, W, H, sx, sy, bm } = layout(code, opts);
  runsToBits(paths[c.symbol], W, sx, sy, bm);
  return { w: W, h: H, bits: bm.b };
}

// <bp-stamp country="DK|auto" fallback="BD" season="fall|auto|none" year="2026|auto|none" tag="true|false"
//           label="en|bn|code|none" frame="perforated|line|none" size="96"></bp-stamp>
if (typeof customElements !== 'undefined' && !customElements.get('bp-stamp')) {
  customElements.define('bp-stamp', class extends HTMLElement {
    static observedAttributes = ['country', 'fallback', 'season', 'year', 'tag', 'label', 'frame', 'size'];
    connectedCallback() { this.render(); }
    attributeChangedCallback() { if (this.isConnected) this.render(); }
    render() {
      const want = (this.getAttribute('country') || 'auto').trim();
      const c = stampFor((want.toLowerCase() === 'auto' ? detectCountry() : want) || this.getAttribute('fallback'));
      if (!c) { this.innerHTML = ''; return; }
      const a = k => this.getAttribute(k);
      const mode = a('label') || 'en', size = parseFloat(a('size')) || 96;
      const text = mode === 'bn' ? c.bn : mode === 'en' ? c.name : mode === 'code' ? c.code : '';
      Object.assign(this.style, { display: 'inline-flex', flexDirection: 'column', alignItems: 'center', gap: '0.4em' });
      this.dataset.country = c.code;
      this.innerHTML = stampSVG(c.code, { size, frame: a('frame') || 'perforated', season: a('season') || 'auto', year: a('year') || 'auto', tag: a('tag') !== 'false' }) +
        (text ? '<span aria-hidden="true" style="font-size:' + Math.max(10, size / 8) + 'px;line-height:1.2;text-align:center;max-width:' + size * 1.4 + 'px">' + esc(text) + '</span>' : '');
    }
  });
}
